#include <bits/stdc++.h>
#define int long long
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> grid(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> grid[i][j];
        }
    }
    const int MOD = 1000000007;
    int total_sum = 0;
    for (int subset_mask = 0; subset_mask < (1 << n); ++subset_mask) {
        int product_value = 1;
        for (int col_idx = 0; col_idx < n; ++col_idx) {
            int val = 1;
            for (int row_idx = 0; row_idx < n; ++row_idx) {
                if (subset_mask & (1 << row_idx))
                    val = (val * grid[row_idx][col_idx]) % MOD;
                else
                    val = (val * (MOD + 1 - grid[row_idx][col_idx]) % MOD) % MOD;
            }
            product_value = (product_value * val) % MOD;
        }
        total_sum = (total_sum + product_value) % MOD;
    }
    cout << total_sum << "\n";
    return 0;
}
